let rng = null;
let score = 0;
let lives = 3;
let gameState = 'PLAYING';

const TILE_SIZE = 20;
const COLS = 20;
const ROWS = 20;
const GRAVITY = 0.6;
const MAX_FALL = 8;
const JUMP_FORCE = -8.5;
const SPEED = 3.5;
const CLIMB_SPEED = 2.5;

let mapGrid = [];
let enemies = [];
let keysList = [];
let treasure = null;
let player = null;

function mulberry32(seed) {
  let t = seed >>> 0;
  return () => {
    t += 0x6D2B79F5;
    let n = Math.imul(t ^ (t >>> 15), t | 1);
    n ^= n + Math.imul(n ^ (n >>> 7), n | 61);
    return ((n ^ (n >>> 14)) >>> 0) / 4294967296;
  };
}

function setup() {
  createCanvas(400, 400);
}

function getGameState() {
  return {
    score: score,
    lives: lives,
    gameState: gameState
  };
}

function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 3;
  gameState = 'PLAYING';
  generateLevel();
}

function generateLevel() {
  for (let r = 0; r < ROWS; r++) {
    mapGrid[r] = [];
    for (let c = 0; c < COLS; c++) {
      if (r === 0 || r === ROWS - 1 || c === 0 || c === COLS - 1) mapGrid[r][c] = 1;
      else mapGrid[r][c] = 0;
    }
  }

  let floorRows = [4, 9, 14, 18];
  for (let f of floorRows) {
    for (let c = 1; c < COLS - 1; c++) {
      mapGrid[f][c] = 1;
    }
  }

  let ladders = [];
  for (let i = 0; i < floorRows.length - 1; i++) {
    let topR = floorRows[i];
    let botR = floorRows[i + 1];
    let ladC = Math.floor(rng() * 14) + 3;
    mapGrid[topR][ladC] = 4; 
    for (let r = topR + 1; r < botR; r++) {
      mapGrid[r][ladC] = 2;
    }
    ladders.push({ f: topR, c: ladC });
  }

  for (let f of floorRows) {
    if (f !== 18) {
      let gap;
      let valid;
      let attempts = 0;
      do {
        valid = true;
        gap = Math.floor(rng() * 13) + 3;
        for (let l of ladders) {
          if (Math.abs(l.f - f) <= 5 && Math.abs(l.c - gap) <= 2) {
            valid = false;
          }
        }
        attempts++;
      } while (!valid && attempts < 50);

      if (valid) {
        mapGrid[f][gap] = 0;
        mapGrid[f][gap + 1] = 0;
      }
    }
  }

  mapGrid[2][14] = 1; 
  mapGrid[3][14] = 3; 
  treasure = { x: 17 * TILE_SIZE + TILE_SIZE / 2, y: 4 * TILE_SIZE - 6, active: true };

  keysList = [];
  let keyF = floorRows[Math.floor(rng() * 2) + 1]; 
  let keyC = Math.floor(rng() * 10) + 2;
  if (mapGrid[keyF][keyC] === 0) keyC++;
  keysList.push({ x: keyC * TILE_SIZE + TILE_SIZE / 2, y: keyF * TILE_SIZE - 5, active: true });

  enemies = [];
  for (let i = 1; i <= 3; i++) {
    let f = floorRows[i];
    let eCol = Math.floor(rng() * 10) + 5;
    if (mapGrid[f][eCol] === 0) continue; 
    enemies.push({
      x: eCol * TILE_SIZE + TILE_SIZE / 2,
      y: f * TILE_SIZE - 6,
      vx: (rng() > 0.5 ? 1 : -1) * (1 + rng() * 1.5),
