function checkCollisions(px, py, w, h, vy, downPressed) {
  let left = Math.floor((px - w / 2 + 0.1) / TILE_SIZE);
  let right = Math.floor((px + w / 2 - 0.1) / TILE_SIZE);
  let top = Math.floor((py - h / 2 + 0.1) / TILE_SIZE);
