    if (!isGrounded) {
      player.vy += GRAVITY;
      if (player.vy > MAX_FALL) player.vy = MAX_FALL;
    } else {
      player.vy = 0;
      player.y = Math.floor((player.y + player.h / 2 + 1) / TILE_SIZE) * TILE_SIZE - player.h / 2 - 0.1;
    }
